mapper.select:
SELECT

FROM
    dm_sec_referer
WHERE
    ref_spec  = #{refSpecId}
    AND
    ref_kind  = #{ruleKind, javaType=com.clougence.clouddm.platform.dal.model.secrule.RuleKind}
    AND
    owner_uid = #{ownerUid}

SELECT

FROM
    dm_sec_referer
WHERE
    owner_uid = #{ownerUid}
    AND
    ref_rule  = #{refRuleOrSenId}
    AND
    ref_kind  = #{ruleKind, javaType=com.clougence.clouddm.platform.dal.model.secrule.RuleKind}

SELECT

FROM
    dm_sec_referer
WHERE
    owner_uid = #{ownerUid}
    AND
    ref_spec  = #{refSpecId}
    AND
    ref_rule  = #{refRuleOrSenId}
    AND
    ref_kind  = #{ruleKind, javaType=com.clougence.clouddm.platform.dal.model.secrule.RuleKind}
LIMIT 1

mapper.delete:
DELETE FROM
    dm_sec_referer
WHERE
    owner_uid = #{ownerUid}
    AND
    ref_spec  = #{refSpecId}

DELETE FROM
    dm_sec_referer
WHERE
